          .run(idempotency.key, idempotency.fingerprint, id);
      }
      return { kind: 'created', job: this.getJob(id) as Job };
    });
  }

  /** Takes the oldest queued job that is due, marks it running and counts the new attempt. */
  claimNext(now: number): Job | undefined {
    return this.tx(() => {
      const row = this.db
        .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`)
        .get(now) as unknown as { id: string } | undefined;
      if (!row) return undefined;
      this.db
        .prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0, updated_at = ? WHERE id = ?`)
        .run(new Date().toISOString(), row.id);
      return this.getJob(row.id);
    });
  }

  setProgress(id: string, completed: number): void {
    this.db
      .prepare(`UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(completed, new Date().toISOString(), id);
  }

  /** Puts a failed attempt back in the queue, due at `runAfter` (epoch ms). */
  scheduleRetry(id: string, runAfter: number): void {
    this.db
      .prepare(`UPDATE jobs SET status = 'queued', completed_steps = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(runAfter, new Date().toISOString(), id);
  }

  completeJob(id: string, output: string): void {
    this.db
      .prepare(
        `UPDATE jobs SET status = 'completed', output = ?, error = NULL, completed_steps = steps, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      )
      .run(encodeText(output), new Date().toISOString(), id);
  }

  failJob(id: string, error: string): void {
    this.db
      .prepare(`UPDATE jobs SET status = 'failed', output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`)
      .run(error, new Date().toISOString(), id);
  }

  /**
   * Recovers jobs whose attempt was interrupted (worker stopped or killed). The interrupted attempt
   * counts as a failed attempt: the job is requeued if attempts remain, otherwise it fails. So
   * `attempts` always equals the number of attempts started, and the MAX_ATTEMPTS limit holds.
   * `where` selects the jobs; `params` are its bound values. Returns the number of jobs changed.
   */
  private recover(where: string, params: (string | number)[]): number {
    const result = this.db
      .prepare(
        `UPDATE jobs SET
           status = CASE WHEN attempts >= ${MAX_ATTEMPTS} THEN 'failed' ELSE 'queued' END,
           error = CASE WHEN attempts >= ${MAX_ATTEMPTS} THEN 'transient failure' ELSE NULL END,
           output = NULL,
           completed_steps = 0,
           run_after = 0,
           updated_at = ?
         WHERE status = 'running' AND ${where}`,
      )
      .run(new Date().toISOString(), ...params);
    return Number(result.changes);
  }

  /** Startup recovery: every job left "running" by a previous worker. */
  requeueRunning(): number {
    return this.recover('1 = 1', []);
  }

  /** Graceful shutdown: the attempt in progress was cut short. */
  interrupt(id: string): void {
    this.recover('id = ?', [id]);
  }

  heartbeat(now: number): void {
    this.db
      .prepare(`INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`)
      .run(now);
  }

  clearHeartbeat(): void {
    this.db.prepare(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
  }

  workerUp(now: number): boolean {
    const row = this.db.prepare(`SELECT at FROM heartbeats WHERE name = 'worker'`).get() as unknown as { at: number } | undefined;
    return row !== undefined && now - row.at <= HEARTBEAT_STALE_MS;
  }
}

import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { JobStore, MAX_ATTEMPTS, type Job } from './store.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
const store = new JobStore(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

// A previous worker that died mid-attempt left jobs as "running". Requeue them: they run again.
const requeued = store.requeueRunning();
if (requeued > 0) console.log(`requeued ${requeued} interrupted job(s)`);

store.heartbeat(Date.now());
const heartbeat = setInterval(() => store.heartbeat(Date.now()), HEARTBEAT_MS);

/** Runs one attempt of a job. The attempt number is `job.attempts`, already counted when claimed. */
async function runAttempt(job: Job): Promise<void> {
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      store.interrupt(job.id);
      return;
    }
    if (attempt <= job.failAttempts) {
      // Simulated transient failure: it happens at the first step, before any progress.
      if (attempt < MAX_ATTEMPTS) store.scheduleRetry(job.id, Date.now() + RETRY_DELAY_MS);
      else store.failJob(job.id, 'transient failure');
      return;
    }
    store.setProgress(job.id, step);
  }
  store.completeJob(job.id, job.input.toUpperCase());
}

console.log('worker started');
while (!stopping) {
  const job = store.claimNext(Date.now());
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeat);
store.clearHeartbeat();
db.close();
console.log('worker stopped');
